<template><div class="app-container"><el-form :inline="true" :model="query"><el-form-item label="订单号"><el-input v-model="query.number" clearable/></el-form-item><el-form-item label="状态"><el-select v-model="query.approvalStatus" clearable><el-option label="草稿" value="DRAFT"/><el-option label="审批中" value="IN_REVIEW"/><el-option label="退回" value="RETURNED"/><el-option label="已通过" value="APPROVED"/></el-select></el-form-item><el-form-item><el-button type="primary" @click="getList">查询</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form><el-button type="primary" plain class="mb8" @click="openEdit">新增订单</el-button><el-table v-loading="loading" :data="list"><el-table-column prop="number" label="订单号" min-width="180"/><el-table-column prop="supplierName" label="供应商" min-width="160"/><el-table-column prop="buyerId" label="采购员ID" width="120"/><el-table-column label="价税合计" width="130"><template #default="s">¥{{((s.row.totalCents||0)/100).toFixed(2)}}</template></el-table-column><el-table-column prop="approvalStatus" label="状态" width="110"/><el-table-column label="操作" width="140"><template #default="s"><el-button link @click="openEdit(s.row)" v-if="['DRAFT','RETURNED'].includes(s.row.approvalStatus)">编辑</el-button><el-button link @click="submit(s.row)" v-if="['DRAFT','RETURNED'].includes(s.row.approvalStatus)">提交</el-button></template></el-table-column></el-table><pagination v-show="total>0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="getList"/><el-dialog v-model="visible" title="采购订单" width="1000px"><el-form ref="formRef" :model="form" :rules="rules" label-width="110px"><el-form-item label="供应商" prop="supplierId"><el-select v-model="form.supplierId" filterable><el-option v-for="item in supplierOptions" :key="item.documentId" :label="`${item.name}（${item.taxId}）`" :value="item.documentId"/></el-select></el-form-item><el-form-item label="采购员" prop="buyerId"><el-select v-model="form.buyerId" filterable><el-option v-for="item in buyerOptions" :key="item.userId" :label="`${item.nickName}（${item.userName}）`" :value="String(item.userId)"/></el-select></el-form-item><el-form-item label="预计到货"><el-date-picker v-model="form.expectedDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-table :data="form.lines" border><el-table-column label="商品"><template #default="s"><el-input v-model="s.row.name"/></template></el-table-column><el-table-column label="单位" width="100"><template #default="s"><el-input v-model="s.row.unit"/></template></el-table-column><el-table-column label="数量" width="130"><template #default="s"><el-input-number v-model="s.row.quantity" :min="0" :precision="4"/></template></el-table-column><el-table-column label="单价" width="140"><template #default="s"><el-input-number v-model="s.row.price" :min="0" :precision="6"/></template></el-table-column><el-table-column label="税率（比例）" width="120"><template #default="s"><el-input-number v-model="s.row.rate" :min="0" :max="1" :precision="4" :step="0.01"/></template></el-table-column><el-table-column label="操作" width="70"><template #default="s"><el-button link type="danger" @click="form.lines?.splice(s.$index,1)">删</el-button></template></el-table-column></el-table><el-button class="mt8" @click="addLine">添加明细</el-button></el-form><template #footer><el-button type="primary" @click="save">保存</el-button><el-button @click="visible=false">取消</el-button></template></el-dialog></div></template>
<script setup lang="ts" name="SupplyOrder">
import { addOrder,getOrder,listOrders,listSuppliers,submitOrder,updateOrder } from '@/api/supply'; import { listUser } from '@/api/system/user'; import type { PurchaseOrder,Supplier } from '@/types/api/supply'; import type { SysUser } from '@/types'
const {proxy}=getCurrentInstance()!; const list=ref<PurchaseOrder[]>([]); const supplierOptions=ref<Supplier[]>([]); const buyerOptions=ref<SysUser[]>([]); const loading=ref(false); const total=ref(0); const visible=ref(false); const formRef=ref(); const form=ref<PurchaseOrder>({lines:[]}); const query=reactive({pageNum:1,pageSize:20,number:undefined as string|undefined,approvalStatus:undefined as string|undefined}); const rules={supplierId:[{required:true,message:'请选择供应商',trigger:'change'}],buyerId:[{required:true,message:'请选择采购员',trigger:'change'}]}
async function getList(){loading.value=true;try{const r=await listOrders(query);list.value=r.rows;total.value=r.total}finally{loading.value=false}};async function openEdit(row?:PurchaseOrder){const [s,u]=await Promise.all([listSuppliers({approvalStatus:'APPROVED',pageNum:1,pageSize:100}),listUser({pageNum:1,pageSize:100,status:'0'})]);supplierOptions.value=s.rows;buyerOptions.value=u.rows;if(row?.documentId){const x=await getOrder(row.documentId);form.value=x.data}else form.value={lines:[{name:'',unit:'',quantity:1,price:0,rate:0.13}]};visible.value=true};function addLine(){(form.value.lines ||= []).push({name:'',unit:'',quantity:1,price:0,rate:0.13})};async function save(){await formRef.value.validate();if(form.value.documentId)await updateOrder(form.value);else await addOrder(form.value);proxy.$modal.msgSuccess('保存成功');visible.value=false;getList()};function submit(row:PurchaseOrder){proxy.$modal.confirm(`确认提交订单“${row.number}”吗？`).then(()=>submitOrder(row.documentId!)).then(()=>{proxy.$modal.msgSuccess('已提交');getList()}).catch(()=>{})};function reset(){query.pageNum=1;query.number=undefined;query.approvalStatus=undefined;getList()};getList()
</script>
